adcs_vec3_t realized_zero = {0, 0, 0};
double b_norm;
unint32 i;
int has_active_axis = 0;
adcs_vec3_t captured_vec = {0, 0, 0};
int is_reversal = 0;

// 1. Disable Logic
if (!mp_input.enable) {
    mp_state.mode = MP_IDLE;
    mp_state.elapsed = 0;
    mp_state.thermal_cycles = 0;
    mp_state.recovery_count = 0;
    mp_state.captured_a_m2 = realized_zero;
    mp_state.last_capture_a_m2 = realized_zero;
    mp_output.mode = MP_IDLE;
    mp_output.realized_a_m2 = realized_zero;
    mp_output.torque_nm = realized_zero;
    mp_output.elapsed = 0;
    mp_output.thermal_cycles = 0;
    mp_output.recovery_count = 0;
    return;
}

// 2. Input Validation
if ((mp_input.request_a_m2 == NULL) || (mp_input.field_body_t == NULL) ||
    !adcs_is_finite_vec3(mp_input.request_a_m2) || !adcs_is_finite_vec3(mp_input.field_body_t)) {
    mp_state.mode = MP_FAULT;
    mp_output.mode = MP_FAULT;
    mp_output.realized_a_m2 = realized_zero;
    mp_output.torque_nm = realized_zero;
    mp_output.elapsed = mp_state.elapsed;
    mp_output.thermal_cycles = mp_state.thermal_cycles;
    mp_output.recovery_count = mp_state.recovery_count;
    return;
}

// 3. Fault Handling
if (mp_state.mode == MP_FAULT) {
    mp_output.mode = MP_FAULT;
    mp_output.realized_a_m2 = realized_zero;
    mp_output.torque_nm = realized_zero;
    mp_output.elapsed = mp_state.elapsed;
    mp_output.thermal_cycles = mp_state.thermal_cycles;
    mp_output.recovery_count = mp_state.recovery_count;
    return;
}

// 4. Field Norm Check
b_norm = adcs_vec3_norm(mp_input.field_body_t);
if (b_norm <= ADCS_EPS_NORM) {
    if (mp_state.mode == MP_PULSE) {
         mp_state.mode = MP_COOLDOWN;
         mp_state.elapsed = 0;
    } else if (mp_state.mode == MP_IDLE) {
         mp_output.mode = MP_IDLE;
         mp_output.realized_a_m2 = realized_zero;
         mp_output.torque_nm = realized_zero;
         mp_output.elapsed = mp_state.elapsed;
         mp_output.thermal_cycles = mp_state.thermal_cycles;
         mp_output.recovery_count = mp_state.recovery_count;
         return;
    }
}

const adcs_vec3_t *req = mp_input.request_a_m2;
const adcs_vec3_t *last_cap = &mp_state.last_capture_a_m2;

// Reset captured vec
captured_vec.x = 0; captured_vec.y = 0; captured_vec.z = 0;
has_active_axis = 0;

for (i = 0; i < 3; i++) {
    double req_val = (i==0)?req->x:(i==1)?req->y:req->z;
    double last_val = (i==0)?last_cap->x:(i==1)?last_cap->y:last_cap->z;
    double abs_r = fabs(req_val);

    int was_active = (fabs(last_val) > FLT64_ZERO); 
    int active = 0;

    if (was_active) {
        if (((req_val > 0 && last_val > 0) || (req_val < 0 && last_val < 0)) && 
            (abs_r > mp_config.stop_fraction * mp_config.max_dipole_a_m2)) {
            active = 1;
        }
    } else {
        if (abs_r > mp_config.start_fraction * mp_config.max_dipole_a_m2) {
            active = 1;
        }
    }

    if (active) {
        has_active_axis = 1;
        double val = req_val;
        if (val > mp_config.max_dipole_a_m2) val = mp_config.max_dipole_a_m2;
        if (val < -mp_config.max_dipole_a_m2) val = -mp_config.max_dipole_a_m2;

        if (i==0) captured_vec.x = val;
        else if (i==1) captured_vec.y = val;
        else captured_vec.z = val;
    }
}

// Global Reversal Check
if (has_active_axis) {
    double dot = adcs_vec3_dot(req, &mp_state.last_capture_a_m2);
    if (dot < 0) {
        is_reversal = 1;
    }
}

// State Machine Execution
switch (mp_state.mode) {
    case MP_IDLE:
        if (is_reversal) {
            mp_state.mode = MP_REVERSAL_WAIT;
            mp_state.elapsed = 0;
        } else if (!has_active_axis) {
            mp_state.mode = MP_COOLDOWN;
            mp_state.elapsed = 0;
        } else {
            if (mp_state.thermal_cycles + 1 > mp_config.max_thermal_cycles) {
                mp_state.mode = MP_INHIBIT;
                mp_state.recovery_count = 0;
            } else {
                mp_state.mode = MP_PULSE;
                mp_state.captured_a_m2 = captured_vec;
                mp_state.last_capture_a_m2 = captured_vec;
                mp_state.elapsed = 1;
                mp_state.thermal_cycles++;
            }
        }
        break;

    case MP_PULSE:
        mp_output.realized_a_m2 = mp_state.captured_a_m2;
        mp_state.elapsed++;
        if (mp_state.elapsed >= mp_config.pulse_cycles) {
            mp_state.mode = MP_COOLDOWN;
            mp_state.elapsed = 0;
        }
        break;

    case MP_COOLDOWN:
        mp_output.realized_a_m2 = realized_zero;
        mp_state.elapsed++;
        if (mp_state.elapsed >= mp_config.cooldown_cycles) {
            mp_state.mode = MP_IDLE;
            mp_state.elapsed = 0;
        }
        break;

    case MP_REVERSAL_WAIT:
        mp_output.realized_a_m2 = realized_zero;
        mp_state.elapsed++;
        if (mp_state.elapsed >= mp_config.reversal_blank_cycles) {
            mp_state.mode = MP_IDLE;
            mp_state.elapsed = 0;
            mp_state.last_capture_a_m2 = realized_zero;
        }
        break;

    case MP_INHIBIT:
        mp_output.realized_a_m2 = realized_zero;
        int quiet = 1;
        for(i=0; i<3; i++) {
             double req_val = (i==0)?req->x:(i==1)?req->y:req->z;
             double thresh = mp_config.stop_fraction * mp_config.max_dipole_a_m2;
             if (fabs(req_val) > thresh) {
                 quiet = 0;
                 break;
             }
        }
        if (quiet) {
            mp_state.recovery_count++;
        } else {
            mp_state.recovery_count = 0;
        }

        if (mp_state.recovery_count >= mp_config.recovery_cycles) {
            mp_state.mode = MP_IDLE;
            mp_state.elapsed = 0;
            mp_state.thermal_cycles = 0;
            mp_state.recovery_count = 0;
        }
        break;

    default:
        break;
}

mp_output.mode = mp_state.mode;
mp_output.elapsed = mp_state.elapsed;
mp_output.thermal_cycles = mp_state.thermal_cycles;
mp_output.recovery_count = mp_state.recovery_count;

if (mp_state.mode != MP_PULSE) {
    mp_output.realized_a_m2 = realized_zero;
}

mp_output.torque_nm = adcs_vec3_cross(&mp_output.realized_a_m2, mp_input.field_body_t);

