// 1. Input Validation and Fault Handling
int enable = mp_input.enable;
const adcs_vec3_t *req = mp_input.request_a_m2;
const adcs_vec3_t *field = mp_input.field_body_t;

// Check pointers
if ((req == NULL) || (field == NULL)) {
    mp_state.mode = MP_FAULT;
    mp_output.mode = MP_FAULT;
    mp_output.elapsed = 0;
    mp_output.thermal_cycles = 0;
    mp_output.recovery_count = 0;
    mp_output.realized_a_m2 = (adcs_vec3_t){0, 0, 0};
    mp_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    return;
}

// Check enable validity (binary)
if (enable != 0 && enable != 1) {
     mp_state.mode = MP_FAULT;
     mp_output.mode = MP_FAULT;
     mp_output.elapsed = 0;
     mp_output.thermal_cycles = 0;
     mp_output.recovery_count = 0;
     mp_output.realized_a_m2 = (adcs_vec3_t){0, 0, 0};
     mp_output.torque_nm = (adcs_vec3_t){0, 0, 0};
     return;
}

// If disabled, clear state
if (!enable) {
    mp_state.mode = MP_IDLE;
    mp_state.elapsed = 0;
    mp_state.thermal_cycles = 0;
    mp_state.recovery_count = 0;
    mp_state.captured_a_m2 = (adcs_vec3_t){0, 0, 0};
    mp_state.last_capture_a_m2 = (adcs_vec3_t){0, 0, 0};

    mp_output.mode = MP_IDLE;
    mp_output.elapsed = 0;
    mp_output.thermal_cycles = 0;
    mp_output.recovery_count = 0;
    mp_output.realized_a_m2 = (adcs_vec3_t){0, 0, 0};
    mp_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    return;
}

// Check for finite inputs
int req_finite = adcs_is_finite_vec3(req);
int field_finite = adcs_is_finite_vec3(field);

double b_norm = 0.0;
if (field_finite) {
