                // Normal Pulse Entry
                mp_state.thermal_cycles++;

                // Check Thermal Budget
                if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
                    mp_state.mode = MP_INHIBIT;
                    mp_state.elapsed = 0;
                    mp_state.recovery_count = 0;
                    mp_output.mode = MP_INHIBIT;
                    mp_output.elapsed = 0;
                    // Emits zero as per requirement for this specific call
                } else {
                    mp_state.mode = MP_PULSE;
                    mp_state.elapsed = 1;
                    mp_state.captured_a_m2 = captured;
                    mp_state.last_capture_a_m2 = captured; // Update last emission

                    mp_output.mode = MP_PULSE;
                    mp_output.elapsed = 1;
                    mp_output.realized_a_m2 = captured;
                    mp_output.torque_nm = adcs_vec3_cross(&captured, &fld);
                }
            }
        }
        return;
    }

    case MP_PULSE:
        mp_state.elapsed++;
        if (mp_state.elapsed >= mp_config.pulse_cycles) {
            mp_state.mode = MP_COOLDOWN;
            mp_state.elapsed = 0;
            mp_output.mode = MP_COOLDOWN;
            mp_output.elapsed = 0;
        } else {
            mp_output.mode = MP_PULSE;
            mp_output.elapsed = mp_state.elapsed;
            mp_output.realized_a_m2 = mp_state.captured_a_m2;
            mp_output.torque_nm = adcs_vec3_cross(&mp_state.captured_a_m2, &fld);
        }
        return;

    case MP_FAULT:
        mp_output.mode = MP_FAULT;
        mp_output.elapsed = 0;
        return;
